"zf1ia4": "Nothing: it's my first client and I want references.",
"u5s33j": "Worked for free for the first client.",
"gys91e": "Free? Nothing's free, {g:lad|love|dear}. Well... I'll pay you in bread. And I'll speak well of you.",
"fuovr": "€450: plan, execution and final report.",
"1nz587r": "That's fair. If it works, I'll be happy.",
