"ku1vd8": "Concentrating it on one day prevents learning and optimisation.",
"ycwaap": "Conversion not set up",
"ck4ccq": "Without measuring sign-ups you don't know what works or what they cost.",
"161m7sb": "Ad: real photo and “first week free”",
"bbp61e": "It's good creative: real and with a clear offer.",
"d2flxj": "A short form is good practice.",
"u8og2t": "Age 18–65",
"gygax1": "Broad but reasonable for a gym; not the main problem.",
"nsa7sv": "Switching the objective to “leads” made the platform look for people willing to sign up.",
"scjtk": "Limiting the location to 12 km around Vic removed thousands of useless impressions.",
"r1s6a6": "Spreading the budget across every day allowed the campaign to be optimised.",
"g9k0rc": "With the conversion set up, you now know exactly what each sign-up costs.",
"enqu5a": "The first €300 was lost by rushing the setup. Mistake owned and fixed.",
"nvwd6k": "Insisting on defining the objective before investing avoided losing money.",
"1w5sr2q": "Gym campaign fixed",
"zozof8": "New sign-ups",
"2eb2u0": "Spend",
"z237g": "Cost per sign-up",
"ba5r3n": "Irrelevant 😉",
"7w28zn": "The fixed campaign works. Toni can't believe it.",
"1gzjfh0": "Better, but there were still mistakes in the setup.",
"6pmgtm": "There are still basic mistakes you haven't spotted.",
"15hj4pj": "Twenty sign-ups! And now I know what each one costs me. You're a star, {nom}.",
