"1jfol1v": "View results",
"v4zg8p": "Students who enter a class code in the game send their results automatically every time they finish a chapter. You can also add results files they've sent you (button below).",
"2tgm8x": "📊 Students",
"7cl6pj": "📂 Add student files",
