"jgc384": "Delivered the website “{0}” built with {1}.",
"1eskckz": "Got it! Thanks so much, {nom}. I'm showing it to everyone right now.",
"1ni9flb": "Website delivered!",
"4e8hel": "Delivery updated. Rewards are only given the first time.",
"1p8q9qu": "New brief unlocked:",
"hzlhoe": "You've completed the Web workshop!",
"yk5t86": "Websites",
"1c8dh49": "Chosen platforms:",
"1twoarw": "Platform",
"1d2dxlk": "Link",
"v387w8": "Websites delivered",
"woqk3l": "Web platforms",
"10vfphl": "Website {0} · platform",
"unkbv9": "Website {0} · link",
"uaxgm3": "Throughout the game, the agency's clients will ask you for real work: plans, campaigns, ads, reports and proposals. Answering questions isn't enough: you have to actually do the work, hand it in and wait for your teacher to approve it before the campaign can continue.",
"ixlzbz": "1. Read the brief and the guide",
"pbk1mx": "Each project has a guide with what it must contain, the steps, the recommended tools and how it will be assessed. Read it all before you start.",
"w20e5w": "2. Use the game's data",
"ac0vgp": "The companies are fictional, but what you discovered while playing (problems, budgets, audiences, results) is your starting information. Add real market data (Idescat, INE, Google Trends, real local competitors) and mark anything you make up as an “assumption”.",
"11gradt": "3. Create the document",
"156l126": "Use Google Docs, Google Slides, Canva, Word or PowerPoint online. Follow the guide's structure: you can copy the template from the game or from this page.",
"pdpjp2": "4. Share it properly",
"1khc0pc": "Open the sharing options and choose “Anyone with the link can view”. If your teacher can't open it, it will be sent back without a review.",
"absca6": "5. Hand it in from the game",
"wgalmq": "📋 Projects tab: paste the link, tick the sections it includes and write a summary of your proposal. You need your teacher's class code.",
"l1hcfv": "6. Wait for the review",
"hyaxkr": "Your teacher can approve it or ask for changes with comments. If they ask for changes, fix the same document (or make a new version) and hand it in again. Meanwhile you can do jobs, lessons and the Web workshop.",
"wicjav": "You can use AI to find ideas, check your writing or generate drafts, but the work must be yours and tailored to the client: at the end of the document, state which AI tools you used and what for. A generic document copied from an AI will be sent back.",
"1u0eu04": "When a project asks for real ads, create them for real: design the pieces (Canva, Adobe Express, CapCut...) and set up the campaign in the real tool (Meta Ads Manager, Google Ads, LinkedIn Campaign Manager) up to the step before publishing, and take screenshots. You don't need to publish or spend money. If you can't create an account, use the official previews and explain this in the note.",
"j33jxs": "Each project is assessed against the criteria in its guide. To pass, it must be complete, tailored to the client and backed by data. Your teacher can also give it a mark from 0 to 10.",
"1dec8vb": "Marketing plan",
"1cm69f3": "Marketing plan for Carme's bakery",
"roahsb": "{nom}, you've explained the plan to me, but I want it in writing. Something I can show my son.",
"wdg4zh": "What we'll do, why, how much it costs and how I'll know if it worked. Clear, and without marketing jargon.",
"1f8vgnt": "A proper marketing plan. This is something I have to do myself, not the game.",
"1jdlpvm": "Write a complete, realistic marketing plan for Carme's bakery, with the €300 budget and the goal of recovering afternoon sales.",
"12zr1i2": "A 4–8 page document (Google Docs, Word or Canva) or a 10–15 slide presentation.",
"1l92k9p": "Executive summary",
"m8e1lg": "In half a page: problem, goal, main actions, budget and how it will be measured. It's what Carme will read first.",
"165bgvi": "Situation analysis",
"1c0zdqd": "What you found out in the interview: quiet time slots, customers, changes in the area (supermarket, school hours), the wrong Google listing. Include a SWOT analysis.",
"qemqrz": "At least two customer profiles (buyer personas): school families, older people from the neighbourhood... What they need, when they pass the bakery and what would make them come in in the afternoon.",
"ojnx0h": "SMART goal",
"uwk3bs": "Specific, measurable, achievable, relevant and time-bound. For example: +15% sales on Tuesdays and Wednesdays from 4 to 7 pm in 4 weeks.",
"1ajpmkz": "Strategy and positioning",
"o75t57": "What main message we'll use and why the bakery is different from the supermarket. A positioning statement.",
"1imzdm0": "Action and channel plan",
"m3wz3i": "For each action: how it's done, where, for whom and who's in charge: Google listing, afternoon snack offer, coupons, local ads... Justify each channel.",
"qus0tk": "Schedule",
"6ub53s": "Timeline for the 4 weeks (table or Gantt chart) with the actions week by week.",
"1wbw6od": "Table showing how the €300 is split by item. Remember: it's the client's money, not agency income.",
"q9zf8f": "Indicators and tracking",
"1wq0gho": "3 or 4 KPIs with the baseline, the target and how and when they'll be measured (till, redeemed coupons, Google listing).",
"1tnh1k9": "Go over your notes from the interview with Carme (chapter 1.2) and the decisions you made in chapter 1.3.",
"1uazkk6": "Look for real data about the area: competitors (bakeries and supermarkets in Vic), school hours, the neighbourhood's population on Idescat.",
"zkbccj": "Do the SWOT and the buyer personas before writing the actions: the actions must come out of the analysis.",
"htzgwb": "Write the plan following the structure and add tables for the schedule, the budget and the KPIs.",
"eci01e": "Reread it with Carme in mind: does it make sense without knowing marketing? Remove unnecessary jargon.",
"1ey44te": "Google Docs or Word · Canva (SWOT and buyer persona templates) · Google Sheets for the budget · Idescat and Google Maps for the area",
"8srzuu": "The analysis is based on client and local data, and the SWOT is consistent",
"1acsohp": "The goal is SMART and linked to the real problem (the afternoons)",
"11ucalv": "The actions are justified and fit the audience and the budget",
"1e9bfkc": "Realistic, well-presented budget and schedule",
"15ibf4s": "Measurable KPIs with baseline and target",
"rxqa9w": "Clear writing, suited to a client who isn't an expert",
"183r3p9": "Common mistake: starting with Instagram. Problem first, then channels.",
"1a8llgp": "If a number is made up, mark it as an assumption and explain where the estimate comes from.",
"e2myi1": "Campaign and ads",
"14n5ftt": "“Afternoon snack” campaign with real ads",
"iad5j3": "I like the plan. Now I want to see the real ads before they go out, so there are no surprises.",
"mx4f09": "And the poster for the school gates, because older people don't look at their phones.",
"1lfn43e": "Real pieces, real copy and the campaign set up in the tool. Let's go.",
"1vrfjvf": "Create the “Afternoon snack” campaign: real ads for Meta and Google, the printed material and the campaign setup ready to publish.",
