"eknzid": "Indicators",
"qma0gs": "How it will be measured: search ranking, calls, bookings, directions and covers on Mondays and Tuesdays.",
"1c7odqf": "Search Google Maps for “restaurant Tona” and analyse how the competitors appear.",
"1ssn53w": "Find keywords with Google's suggestions, Google Trends or the Google Ads Keyword Planner.",
"1h2pwcz": "Write the review replies: thank, personalise and, for negative ones, offer a solution without arguing.",
"8suc4u": "Design the promotion with people who live or work near Tona in mind.",
"od0pzf": "Put everything in a document with screenshots and a priority table.",
"1yjx9qk": "Google Maps and Google Business Profile · Google Trends · Google Ads Keyword Planner · Canva",
"fh6pfv": "The listing audit is complete and includes concrete proposals",
"16s89e4": "The keywords are local and take search intent into account",
"14l1tn7": "The competitor analysis uses real data",
"1mhpfcl": "The review replies are professional and empathetic",
"1t6wiqg": "The promotion targets the local audience and can be measured",
"11bs36s": "Common mistake: thinking about followers. Can Jordi needs people who can come for lunch on a Monday.",
"qx7z03": "A reply to a negative review is read by future customers, not just by the person who wrote it.",
