"1bothas": "6. Marking and review",
"17k4sbq": "Within a few minutes, AI automatic marking reads your document, scores it against the rubric and gives you feedback. Your teacher can review and change it at any time. If it needs work, fix the document and hand it in again. Meanwhile you can do jobs, lessons and the Web workshop.",
"16v4evn": "Each project is assessed with the rubric in its guide: each criterion has 4 levels (0 to 3 points) and the mark is the proportion of points scored out of 10. You pass with a 5. Automatic marking can only read public Google documents (Docs, Slides, Sheets), PDFs, images and web pages: if you use Canva or video, also hand in a PDF. Your teacher always decides the final mark.",
