"4hr3j6": "The bakery's Google listing says it closes at 2 pm: lots of people think it's closed in the afternoon.",
"35spqd": "In the afternoon, the shelf is full of unsold crystal flatbread and sandwich loaves.",
"1qxr9ks": "The till receipts: 72% of sales are in the morning. On Tuesday and Wednesday afternoons almost nothing sells.",
