"1cntweq": "School now finishes at 4:30 pm, half an hour earlier: families no longer pass the bakery at snack time.",
"1e08uxp": "In the morning, older people from the neighbourhood come in; in the afternoon it used to be mainly school families.",
"ozl7et": "On Google, Can Jordi doesn't show its set lunch or have a booking button, and there are unanswered reviews.",
"1f8w12n": "On the Tona industrial estate, 3 minutes from the restaurant, hundreds of people work and eat sandwiches for lunch.",
"byod3v": "At lunchtime the phone rings and nobody can answer it: you can only book by phone.",
