"rrhhn1": "New clue for {0}: {1}",
"1532179": "I've been doing clothing alterations for thirty years, but young people don't even know I exist. And I don't have much money to spend.",
"gb8tgb": "Google listing showing the alterations service, before-and-after photos and a sign in the window",
"1ciks9l": "In two weeks, 14 new jobs from people who found her on Google Maps. Montse pays you €180 and recommends you to the whole street.",
"rvc665": "Hand out 2,000 leaflets all over Vic",
"15pkpqs": "Hardly anyone notices the leaflets and no new customers come in. You've fronted €120 for printing that you won't get back.",
"15rzjvh": "Open a TikTok account and post every day",
"10g3t9l": "Two videos do well, but Montse doesn't have time to keep it up. She pays you €40 for the work.",
"i4jn1q": "I've got the best terrace on the square, but tourists sit at the bar next door. I don't get it!",
"9iixkp": "Google listing with terrace photos, a menu in English and French, and kitchen hours",
"1a6h4j": "Tourists search “terrace Vic” on their phones and now they find him. The terrace fills up and Baltasar pays you €220.",
"16uorlc": "Put a waiter on the square to bring customers in",
"l401hh": "Tourists feel pressured and walk on by. You've paid €150 of a week's wages.",
"1ooulfi": "Run a 2-for-1 beer offer",
"m6xgdt": "More people come, but the margin is tiny and they don't come back. He pays you €50.",
"hl2tmn": "Cheese stall",
"htzdpu": "At the Saturday market I sell loads. During the week, nothing. And people from Barcelona ask if I ship cheese.",
"ad04dr": "Orders via WhatsApp Business with a catalogue, plus pick-up or local delivery",
"1u8crtw": "Weekday orders come in on WhatsApp and she now ships to Barcelona. Roser pays you €200.",
"gwb1r0": "Rent a shop in Barcelona",
"j6xt4p": "The deposit and first month's rent eat up all the profit. You'd agreed to pay part of it: −€300.",
"pkiguo": "Sell on Amazon",
"1rzqk2r": "High fees and a price war. She sells little. She pays you €40.",
"ssv33r": "Marisa's Hair Salon",
"16guw4c": "I'm losing appointments! People book on WhatsApp while I'm cutting hair and I forget to reply.",
"o58xbn": "Online booking with automatic reminders, linked from Instagram and Google",
"1dyjopt": "Appointments book themselves and none are forgotten any more. Marisa pays you €160.",
"1eak3vp": "Hire a receptionist just for WhatsApp",
"1wa0dlx": "Too costly for a small business. You'd recommended a recruitment agency and have to pay €250 of the fee.",
"e39xtx": "Reply to messages at night",
"nq7zis": "It works, but Marisa ends up exhausted. She pays you €30.",
"158rlgg": "Chapter {0}: {1}",
"1d1vlt3": "Real project: {0}",
"owyi8x": "Reach level {0} to continue: help the shopkeepers in Vic or do jobs.",
"1hle35a": "I've been going to Carme's bakery every morning for forty years. The afternoon? In the afternoon it was the school families, but not any more.",
"16lbocs": "I wanted bread for an afternoon snack, but Google says Carme's bakery closes at two. Shame, I'll have to go to the supermarket.",
"1gauz76": "This was my toy shop. Thirty-two years. When online shopping arrived, I didn't want to change anything...",
"v6mno1": "If I did it again, I'd listen more to what customers wanted. You do marketing: don't let it happen to the others.",
"1rv59qi": "Thanks for the snack coupon! The kids ask for it every Tuesday now.",
"cl4yw4": "School finishes at half past four now and we go straight to the park. We used to stop at the bakery.",
"1tetk9": "Did you know the supermarket sells croissants for 30 cents? They taste like plastic, but they're cheap!",
"1qo8pxs": "I'm catching the train to Barcelona. Reports first thing on Monday, OK?",
"18ev6c1": "We're open until nine in the evening, every day. In the afternoon lots of people come for baguettes.",
"z9bs8g": "The bread here isn't like the bakery's, but at seven in the evening it's the only place open.",
"5wm3f3": "Carme's crackling flatbread is the best in Vic. But nowhere online says so.",
"17m44qi": "A sandwich at the warehouse every day. Can Jordi? Yes, it's nice, but I didn't know they did a weekday set lunch.",
"1r8zzcw": "I'm one of the few who come on a Monday. I work on the industrial estate and found it by chance.",
"272ped": "I tried to buy fuet online on my phone and the pay button does nothing! I've had to come to the shop.",
"g6jw6j": "Welcome to the fair, competitor. This is where you win the clients who aren't on Google.",
"108gbp": "I've already scheduled this week's posts! What else can I do?",
"2fjs9j": "I've got three meetings this week with companies on the industrial estate. The proposals are on the computer.",
"z1bzcx": "We make parts for farm machinery across half of Europe. But the website... the manager's nephew made it in 2011.",
"1y2smto": "▶ Start the mission",
"1fv8d4y": "Come in, come in! The crystal flatbread came out wonderfully today.",
"1x0jewo": "Monday, the dining room's half empty... If you know how to fill it, lunch is on me.",
"r7k160": "Traditional Vic fuet! Now we ship it all over Catalonia too.",
"p7oh5u": "Look at this new jacket. I've already got the photo for Instagram... or should we look at sales first?",
"lb1u6r": "Nobody talks about followers here. We talk about parts, lead times and buyers.",
"3p5k7e": "Hi!",
"1utkxo3": "What would you like to do?",
"5vm5vc": "Nothing, thanks",
"jqcaxa": "Thanks for the advice! Business is better.",
