"1wwde61": "A dark photo of the counter taken with flash",
"11m502f": "The coca de vidre and bread by the window, in natural light",
"1cq1emq": "A generic logo downloaded from the internet",
"rptl4s": "Real, well-lit photos of the star product: they're what brings people in.",
