"131t40i": "“Come and visit us!”",
"1vl5qov": "Nothing: posts don't work",
"uz1ka8": "News with a specific offer and time slot gives people a reason to come in the afternoon.",
"1qfn65x": "Look! It now says we're open in the afternoon. Three customers came in today after seeing it on their phones!",
