"1bc5t35": "The empty tray. The photos are already on the Google listing.",
"1m23lly": "📸 You want to take product photos for the Google listing. Where do you take them?",
"10ty9uy": "By the window, in natural light against a wooden background",
"1w4bmlb": "Under the counter's fluorescent light",
"15awhs8": "With the phone's flash, up close",
"14igmzy": "Click! The flatbread gleams and the bread looks fresh out of the oven. Catalogue-quality photos.",
"uxp303": "The photos come out greenish and flat. They'll do, but they don't make you hungry.",
"1ghwgjt": "The flash burns out the flatbread and casts harsh shadows. Better not to post them.",
"18dnq11": "Took product photos for the bakery ({0}/3).",
"fgacmk": "A couple have just finished lunch and are smiling. How do you ask them for a review?",
"xwpp9a": "\"If you enjoyed it, a review would really help us: here's the QR code.\"",
"9c2htj": "“Give us five stars and coffee's on us.”",
"l6jq96": "Say nothing and wait for them to do it themselves",
"1ex5vw3": "Asking at the right moment, with the QR code to hand, is honest and effective. Offering gifts in exchange for reviews breaks Google's rules.",
"1cib9w3": "A customer complains that the main course took a long time.",
"2d0b2n": "Ignore him: he'll leave eventually",
"dtt4np": "Apologise, explain and offer dessert on the house",
"1blun70": "Ask him for a five-star review anyway",
"cwjy6o": "Resolving the complaint on the spot prevents a negative review and wins a customer.",
"1shlp21": "Three workers from the industrial estate are having the set lunch for the first time.",
"157hb37": "Give them a card with the weekly menu and WhatsApp for bookings",
"hdvqt2": "Tell them the restaurant's history for half an hour",
"16q76jd": "Nothing: they'll come back",
"1opaool": "Making it easy to come back (menu and easy booking) is what fills Mondays.",
"1v0tphd": "⭐ Reviews at Can Jordi",
"yw1n6i": "Five new reviews in one day and two bookings on WhatsApp! This works.",
