"17a8987": "How it works",
"xq91pw": "If you <b>hire</b> another agency, you pay the price and your client is happy: you gain reputation (more if that agency specialises in the service) and experience. If <b>you're hired</b>, you're paid the price and gain experience. The price is negotiable: you can make up to four counter-offers. Deals expire after 7 days.",
